(function(root,factory){
  const api=factory();
  if(typeof module==='object'&&module.exports) module.exports=api;
  if(root) root.HerdHarborShows=api;
  if(root&&root.document) api.start(root);
})(typeof globalThis!=='undefined'?globalThis:this,function(){
  'use strict';

  const VERSION='1.5.1';
  const STORAGE_KEY='herdharbor_pre_alpha_v1';
  const RETURN_KEY='herdharbor_v150_return_shows';
  const COLLECTIONS=['shows','showEntries','showResults','showAwards','exhibitors','showProjects','projectGoals','projectNotes','projectPhotos'];
  const SHOW_TYPES=['4-H','FFA','County Fair','State Fair','ARBA','Breed Club','Rabbit Show','Poultry Show','Livestock Show','Beef Show','Dairy Show','Goat Show','Sheep Show','Swine Show','Horse Show','Open Show','Youth Show','Other'];
  const AWARD_TYPES=['Champion','Reserve Champion','Grand Champion','Reserve Grand Champion','Best of Breed','Best Opposite Sex','Best in Show','Reserve Best in Show','Best Junior','Best Senior','Showmanship Champion','Showmanship Reserve','Division Champion','Class Winner','Blue Ribbon','Red Ribbon','White Ribbon','Purple Ribbon','Other'];
  const PROJECT_TYPES=['Rabbit','Poultry','Beef','Dairy','Goat','Sheep','Swine','Horse','Dog','Companion Animal','Other'];
  const PROJECT_STATUSES=['Planned','Active','Completed','Archived'];
  const GOAL_STATUSES=['Not Started','In Progress','Completed'];
  const PLACEMENTS=['1st','2nd','3rd','4th','5th','6th','7th','8th','9th','10th','Participated','Did Not Place','Disqualified','Custom'];
  const HEALTH_TYPES=['Weight','Treatment','Medication','Vaccination','Observation','Veterinary visit'];
  const PHOTO_CATEGORIES=['Beginning','Progress','Animal','Project Work','Show','Award','Other'];
  const MAX_ATTACHMENTS=12;
  const MAX_FILE_BYTES=5*1024*1024;
  let ui={tab:'overview',year:String(new Date().getFullYear()),search:'',showType:'',organization:'',species:'',animalId:'',exhibitorId:'',projectId:'',page:1};

  const q=(s,r=document)=>r.querySelector(s);
  const qa=(s,r=document)=>Array.from(r.querySelectorAll(s));
  const now=()=>new Date().toISOString();
  const today=()=>new Date().toISOString().slice(0,10);
  const esc=v=>String(v==null?'':v).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const clean=v=>String(v==null?'':v).trim();
  const money=v=>new Intl.NumberFormat(undefined,{style:'currency',currency:'USD'}).format(Number(v)||0);
  const fmtDate=v=>{if(!v)return'—';const d=new Date(`${String(v).slice(0,10)}T12:00:00`);return Number.isNaN(d.getTime())?esc(v):d.toLocaleDateString();};
  const uid=prefix=>`${prefix}_${Date.now()}_${Math.random().toString(36).slice(2,8)}`;
  const number=v=>Number.isFinite(Number(v))?Number(v):0;
  const safeYear=v=>/^\d{4}$/.test(String(v))?String(v):String(new Date().getFullYear());
  const activeRecord=r=>String(r?.status||'Active').toLowerCase()!=='archived'&&String(r?.status||'Active').toLowerCase()!=='inactive';

  function readState(){
    try{const s=JSON.parse(localStorage.getItem(STORAGE_KEY)||'{}');return s&&typeof s==='object'?s:{};}catch{return{};}
  }
  function normalizeState(state){
    const s=state&&typeof state==='object'?state:{};
    COLLECTIONS.forEach(k=>{if(!Array.isArray(s[k]))s[k]=[];});
    if(!Array.isArray(s.animals))s.animals=[];
    if(!Array.isArray(s.health))s.health=[];
    if(!Array.isArray(s.transactions))s.transactions=[];
    return s;
  }
  function writeState(state,message='Saved.'){
    const next=normalizeState(state);
    localStorage.setItem(STORAGE_KEY,JSON.stringify(next));
    try{sessionStorage.setItem(RETURN_KEY,JSON.stringify({tab:ui.tab,year:ui.year,message}));}catch{}
    location.reload();
  }
  function mutate(message,fn){const s=normalizeState(readState());fn(s);writeState(s,message);}

  function optionList(values,selected='',includeBlank=false,blank='Select…'){
    return `${includeBlank?`<option value="">${esc(blank)}</option>`:''}${values.map(v=>`<option value="${esc(v)}" ${String(v)===String(selected)?'selected':''}>${esc(v)}</option>`).join('')}`;
  }
  function animalOptions(s,selected=''){
    return s.animals.filter(a=>a&&a.id).sort((a,b)=>clean(a.name).localeCompare(clean(b.name))).map(a=>`<option value="${esc(a.id)}" ${a.id===selected?'selected':''}>${esc(a.name||a.id)} · ${esc(a.species||'Animal')}${a.breed?` · ${esc(a.breed)}`:''}</option>`).join('');
  }
  function exhibitorName(s,id){const x=s.exhibitors.find(e=>e.id===id);return x?clean(x.preferredName)||[x.firstName,x.lastName].filter(Boolean).join(' ')||'Unnamed exhibitor':'—';}
  function animalName(s,id){const a=s.animals.find(x=>x.id===id);return a?.name||a?.animalName||a?.registeredName||'—';}
  function showName(s,id){return s.shows.find(x=>x.id===id)?.name||'—';}
  function projectName(s,id){return s.showProjects.find(x=>x.id===id)?.projectName||'—';}
  function resultPlacement(r){if(!r)return'—';if(r.placement==='Custom')return r.customPlacement||'Custom';if(r.placementNumber&&Number(r.placementNumber)>10)return ordinal(Number(r.placementNumber));return r.placement||'—';}
  function ordinal(n){const v=n%100;return `${n}${['th','st','nd','rd'][(v-20)%10]||['th','st','nd','rd'][v]||'th'}`;}
  function showTypeLabel(x){return x.showType==='Other'?(x.customShowType||'Other'):(x.showType||'Other');}
  function awardLabel(a){return a.awardType==='Other'?(a.customAward||'Other'):(a.awardType||'Other');}
  function projectTypeLabel(p){return p.projectType==='Other'?(p.customProjectType||'Other'):(p.projectType||'Other');}
  function showYear(show){return clean(show.startDate).slice(0,4)||'';}
  function selectedYearRows(s){return s.shows.filter(x=>showYear(x)===ui.year);}
  function financialSummary(transactions){
    const income=(transactions||[]).filter(t=>t.type==='Income').reduce((sum,t)=>sum+number(t.amount),0);
    const expenses=(transactions||[]).filter(t=>t.type==='Expense').reduce((sum,t)=>sum+number(t.amount),0);
    return{income,expenses,totalCost:expenses,net:income-expenses};
  }
  function showFinancials(s,showId){return financialSummary(s.transactions.filter(t=>t.showId===showId));}
  function projectFinancials(s,projectId){return financialSummary(s.transactions.filter(t=>t.projectId===projectId));}
  function showEntriesFor(s,showId){return s.showEntries.filter(e=>e.showId===showId);}
  function resultsForEntry(s,entryId){return s.showResults.filter(r=>r.entryId===entryId);}
  function awardsForEntry(s,entryId){return s.showAwards.filter(a=>a.entryId===entryId);}
  function isFirst(r){return r?.placement==='1st'||Number(r?.placementNumber)===1;}
  function isChampionship(a){return /champion|best of breed|best in show|division champion/i.test(awardLabel(a));}

  function animalHistory(s,animalId){
    const entries=s.showEntries.filter(e=>e.animalId===animalId);
    const entryIds=new Set(entries.map(e=>e.id));
    const results=s.showResults.filter(r=>entryIds.has(r.entryId));
    const resultIds=new Set(results.map(r=>r.id));
    const awards=s.showAwards.filter(a=>entryIds.has(a.entryId)||resultIds.has(a.resultId)||a.animalId===animalId);
    const showIds=new Set(entries.map(e=>e.showId));
    return{entries,results,awards,shows:s.shows.filter(x=>showIds.has(x.id)),totals:{shows:showIds.size,classes:entries.length,firstPlaces:results.filter(isFirst).length,championships:awards.filter(isChampionship).length,awards:awards.length}};
  }
  function exhibitorHistory(s,exhibitorId){
    const entries=s.showEntries.filter(e=>e.exhibitorId===exhibitorId);
    const entryIds=new Set(entries.map(e=>e.id));
    const results=s.showResults.filter(r=>entryIds.has(r.entryId));
    const resultIds=new Set(results.map(r=>r.id));
    const awards=s.showAwards.filter(a=>entryIds.has(a.entryId)||resultIds.has(a.resultId)||a.exhibitorId===exhibitorId);
    return{entries,results,awards,totals:{shows:new Set(entries.map(e=>e.showId)).size,animals:new Set(entries.map(e=>e.animalId)).size,classes:entries.length,firstPlaces:results.filter(isFirst).length,championships:awards.filter(isChampionship).length,awards:awards.length}};
  }
  function growthSummary(s,p){
    const rows=s.health.filter(h=>h.animalId===p.animalId&&h.type==='Weight'&&number(h.weight)>0).sort((a,b)=>String(a.date||'').localeCompare(String(b.date||'')));
    if(!rows.length)return{start:null,current:null,gain:null,adg:null};
    const start=rows.find(r=>!p.startDate||!r.date||r.date>=p.startDate)||rows[0],current=rows[rows.length-1];
    const gain=number(current.weight)-number(start.weight);const days=start.date&&current.date?Math.max(0,Math.round((new Date(current.date)-new Date(start.date))/86400000)):0;
    return{start,current,gain,adg:days>0?gain/days:null,days};
  }
  function projectTimeline(s,projectId){
    const p=s.showProjects.find(x=>x.id===projectId);if(!p)return[];const rows=[];
    rows.push({date:p.startDate||p.createdAt?.slice(0,10)||'',type:'Project',title:'Project started',detail:p.projectName});
    s.health.filter(h=>h.animalId===p.animalId).forEach(h=>rows.push({date:h.date,type:'Health',title:h.type,detail:h.details||h.notes||''}));
    s.transactions.filter(t=>t.projectId===projectId).forEach(t=>rows.push({date:t.date,type:'Finance',title:`${t.type}: ${t.category||'Transaction'}`,detail:`${money(t.amount)} ${t.description||''}`.trim()}));
    s.showEntries.filter(e=>e.projectId===projectId).forEach(e=>{const sh=s.shows.find(x=>x.id===e.showId);rows.push({date:sh?.startDate||'',type:'Show',title:sh?.name||'Show entry',detail:e.className||e.division||''});});
    s.projectGoals.filter(g=>g.projectId===projectId&&g.status==='Completed').forEach(g=>rows.push({date:g.completedDate||g.targetDate||'',type:'Goal',title:'Goal completed',detail:g.goal||''}));
    s.projectNotes.filter(n=>n.projectId===projectId).forEach(n=>rows.push({date:n.date,type:'Note',title:n.title||'Project note',detail:n.note||''}));
    s.projectPhotos.filter(ph=>ph.projectId===projectId).forEach(ph=>rows.push({date:ph.date,type:'Photo',title:ph.category||'Photo',detail:ph.caption||''}));
    return rows.sort((a,b)=>String(b.date||'').localeCompare(String(a.date||'')));
  }

  function validateShow(data){if(!clean(data.name))return'Show name is required.';if(!data.startDate)return'Start date is required.';if(data.endDate&&data.endDate<data.startDate)return'End date cannot be before the start date.';return'';}
  function validateEntry(data){if(!data.showId)return'Choose a show.';if(!data.animalId)return'Choose an existing HerdHarbor animal.';if(!data.exhibitorId)return'Choose an exhibitor.';if(data.classEntryCount&&number(data.classEntryCount)<0)return'Class entry count cannot be negative.';if(data.showWeight&&number(data.showWeight)<0)return'Show weight cannot be negative.';return'';}
  function validateResult(data){if(data.placementNumber&&(number(data.placementNumber)<1||!Number.isInteger(number(data.placementNumber))))return'Numeric placement must be a positive whole number.';return'';}
  function validateProject(data){if(!/^\d{4}$/.test(String(data.year)))return'Enter a valid four-digit year.';if(data.endDate&&data.startDate&&data.endDate<data.startDate)return'Project end date cannot be before the start date.';if(!data.exhibitorId)return'Choose an exhibitor.';if(!data.animalId)return'Choose an existing animal.';return'';}

  function setModal(title,html,kicker='Shows'){
    const back=q('#modal-backdrop'),content=q('#modal-content'),heading=q('#modal-title'),kick=q('#modal-kicker'),modal=q('.modal');
    if(!back||!content||!heading)return false;
    modal?.classList.remove('modal-wide');heading.textContent=title;if(kick)kick.textContent=kicker;content.innerHTML=html;back.classList.remove('hidden');back.setAttribute('aria-hidden','false');document.body.classList.add('modal-open');modal?.scrollTo?.(0,0);setTimeout(()=>q('input,select,textarea',content)?.focus(),30);return true;
  }
  function closeModal(){q('#modal-backdrop')?.classList.add('hidden');q('#modal-backdrop')?.setAttribute('aria-hidden','true');document.body.classList.remove('modal-open');if(q('#modal-content'))q('#modal-content').innerHTML='';}
  function feedback(message,type='error'){const r=q('#toast-region');if(!r){alert(message);return;}const n=document.createElement('div');n.className=`toast ${type}`;n.textContent=message;r.appendChild(n);setTimeout(()=>n.remove(),3600);}
  function formActions(primary='Save'){return`<div class="form-actions"><button type="button" class="button button-ghost" data-shows-cancel>Cancel</button><button type="submit" class="button button-primary">${esc(primary)}</button></div>`;}
  function field(label,name,value='',type='text',required=false,extra=''){return`<label>${esc(label)}<input name="${esc(name)}" type="${type}" value="${esc(value)}" ${required?'required':''} ${extra}></label>`;}
  function textarea(label,name,value=''){return`<label>${esc(label)}<textarea name="${esc(name)}" rows="3">${esc(value)}</textarea></label>`;}
  function select(label,name,values,value='',blank=false){return`<label>${esc(label)}<select name="${esc(name)}">${optionList(values,value,blank)}</select></label>`;}
  function attachCancel(root=document){qa('[data-shows-cancel]',root).forEach(b=>b.addEventListener('click',closeModal));}
  async function fileToAttachment(file){if(file.size>MAX_FILE_BYTES)throw new Error(`${file.name} is larger than 5 MB.`);const dataUrl=await new Promise((resolve,reject)=>{const r=new FileReader();r.onload=()=>resolve(r.result);r.onerror=()=>reject(r.error);r.readAsDataURL(file);});return{id:uid('media'),name:file.name,type:file.type||'application/octet-stream',size:file.size,dataUrl,createdAt:now()};}

  function renderAttachmentList(items){if(!items?.length)return'';return`<div class="hh-shows-attachments">${items.map(a=>`<div class="list-item"><div class="list-item-main"><strong>${esc(a.name)}</strong><span>${Math.round(number(a.size)/1024)} KB</span></div><div class="list-item-actions"><a class="button button-ghost button-small" href="${esc(a.dataUrl)}" download="${esc(a.name)}">Open</a></div></div>`).join('')}</div>`;}

  function openShowForm(id=''){
    const s=normalizeState(readState()),x=s.shows.find(r=>r.id===id)||{showType:'County Fair',startDate:today(),status:'Active',attachments:[]};
    setModal(id?'Edit show':'Add show',`<form id="hh-show-form"><div class="form-grid two">${field('Show name','name',x.name,'text',true)}${field('Start date','startDate',x.startDate,'date',true)}${field('End date','endDate',x.endDate,'date')}${field('Location','location',x.location)}${field('City','city',x.city)}${field('State','state',x.state)}${field('Organization','organization',x.organization)}${select('Show type','showType',SHOW_TYPES,x.showType)}${field('Custom show type','customShowType',x.customShowType)}${select('Status','status',['Active','Archived'],x.status||'Active')}</div>${textarea('Notes','notes',x.notes)}<label>Attachments<input id="hh-show-files" type="file" multiple accept="image/*,.pdf,.doc,.docx,.txt"></label><p class="muted">Scorecards, programs, receipts, ribbons, photos, and paperwork. Up to ${MAX_ATTACHMENTS} files per show.</p>${renderAttachmentList(x.attachments||[])}${formActions(id?'Save changes':'Add show')}</form>`);
    attachCancel();q('#hh-show-form').addEventListener('submit',async e=>{e.preventDefault();const data=Object.fromEntries(new FormData(e.currentTarget));const err=validateShow(data);if(err)return feedback(err);let attachments=(x.attachments||[]).slice();try{for(const f of Array.from(q('#hh-show-files').files||[])){if(attachments.length>=MAX_ATTACHMENTS)break;attachments.push(await fileToAttachment(f));}}catch(err){return feedback(err.message);}mutate(id?'Show updated.':'Show added.',state=>{const row={...data,attachments,updatedAt:now()};if(id){const old=state.shows.find(r=>r.id===id);Object.assign(old,row);}else state.shows.push({id:uid('show'),...row,createdAt:now()});});});
  }
  function openExhibitorForm(id=''){
    const s=normalizeState(readState()),x=s.exhibitors.find(r=>r.id===id)||{status:'Active'};
    setModal(id?'Edit exhibitor':'Add exhibitor',`<form id="hh-exhibitor-form"><div class="form-grid two">${field('First name','firstName',x.firstName,'text',true)}${field('Last name','lastName',x.lastName,'text',true)}${field('Preferred name','preferredName',x.preferredName)}${field('Club','club',x.club)}${field('Organization','organization',x.organization)}${field('County','county',x.county)}${field('State','state',x.state)}${field('Member ID','memberId',x.memberId)}${field('Age division','ageDivision',x.ageDivision)}${select('Status','status',['Active','Inactive'],x.status||'Active')}</div>${textarea('Notes','notes',x.notes)}${formActions(id?'Save changes':'Add exhibitor')}</form>`);
    attachCancel();q('#hh-exhibitor-form').addEventListener('submit',e=>{e.preventDefault();const data=Object.fromEntries(new FormData(e.currentTarget));mutate(id?'Exhibitor updated.':'Exhibitor added.',state=>{if(id)Object.assign(state.exhibitors.find(r=>r.id===id),data,{updatedAt:now()});else state.exhibitors.push({id:uid('exhibitor'),...data,createdAt:now()});});});
  }
  function openEntryForm(id='',defaults={}){
    const s=normalizeState(readState());if(!s.shows.filter(activeRecord).length)return feedback('Add a show first.');if(!s.exhibitors.filter(activeRecord).length)return feedback('Add an exhibitor first.');if(!s.animals.length)return feedback('Add an animal before creating show entries.');
    const x=s.showEntries.find(r=>r.id===id)||{showId:defaults.showId||'',exhibitorId:defaults.exhibitorId||'',animalId:defaults.animalId||'',showWeightUnit:'lb',projectId:defaults.projectId||''};
    setModal(id?'Edit entry':'Add show entry',`<form id="hh-entry-form"><div class="form-grid two"><label>Show<select name="showId" required><option value="">Select…</option>${s.shows.filter(activeRecord).map(r=>`<option value="${r.id}" ${r.id===x.showId?'selected':''}>${esc(r.name)} · ${fmtDate(r.startDate)}</option>`).join('')}</select></label><label>Exhibitor<select name="exhibitorId" required><option value="">Select…</option>${s.exhibitors.filter(activeRecord).map(r=>`<option value="${r.id}" ${r.id===x.exhibitorId?'selected':''}>${esc(exhibitorName(s,r.id))}</option>`).join('')}</select></label><label>Animal<select name="animalId" required><option value="">Select…</option>${animalOptions(s,x.animalId)}</select></label><label>Project (optional)<select name="projectId"><option value="">None</option>${s.showProjects.filter(p=>p.status!=='Archived').map(p=>`<option value="${p.id}" ${p.id===x.projectId?'selected':''}>${esc(p.projectName)}</option>`).join('')}</select></label>${field('Division','division',x.division)}${field('Class','className',x.className)}${field('Age class','ageClass',x.ageClass)}${field('Weight class','weightClass',x.weightClass)}${field('Entry number','entryNumber',x.entryNumber)}${field('Entries in class','classEntryCount',x.classEntryCount,'number',false,'min="0" step="1"')}${field('Judge','judge',x.judge)}${field('Showmanship category','showmanshipCategory',x.showmanshipCategory)}${field('Show weight','showWeight',x.showWeight,'number',false,'min="0" step="0.01"')}${select('Weight unit','showWeightUnit',['lb','oz','kg','g'],x.showWeightUnit||'lb')}${field('Body condition','bodyCondition',x.bodyCondition)}${field('Show condition notes','conditionNotes',x.conditionNotes)}</div>${textarea('Notes','notes',x.notes)}${formActions(id?'Save changes':'Add entry')}</form>`,'Shows · Entry');
    attachCancel();q('#hh-entry-form').addEventListener('submit',e=>{e.preventDefault();const data=Object.fromEntries(new FormData(e.currentTarget));const err=validateEntry(data);if(err)return feedback(err);mutate(id?'Show entry updated.':'Show entry added.',state=>{const row={...data,updatedAt:now()};if(id)Object.assign(state.showEntries.find(r=>r.id===id),row);else state.showEntries.push({id:uid('entry'),...row,createdAt:now()});});});
  }
  function openResultForm(entryId,resultId=''){
    const s=normalizeState(readState()),entry=s.showEntries.find(e=>e.id===entryId);if(!entry)return feedback('Show entry not found.');const x=s.showResults.find(r=>r.id===resultId)||{entryId,placement:'Participated',judge:entry.judge||'',attachments:[]};
    setModal(resultId?'Edit result':'Add result',`<form id="hh-result-form"><div class="form-grid two">${select('Placement','placement',PLACEMENTS,x.placement||'Participated')}${field('Numeric placement beyond 10th','placementNumber',x.placementNumber,'number',false,'min="1" step="1"')}${field('Custom placement','customPlacement',x.customPlacement)}${field('Judge','judge',x.judge)}${field('Score','score',x.score)}</div>${textarea('Judge comments','comments',x.comments)}${textarea('Strengths','strengths',x.strengths)}${textarea('Areas for improvement','improvements',x.improvements)}${textarea('Notes','notes',x.notes)}<label>Result photos/documents<input id="hh-result-files" type="file" multiple accept="image/*,.pdf,.doc,.docx,.txt"></label>${renderAttachmentList(x.attachments||[])}${formActions(resultId?'Save changes':'Add result')}</form>`,'Shows · Result');
    attachCancel();q('#hh-result-form').addEventListener('submit',async e=>{e.preventDefault();const data=Object.fromEntries(new FormData(e.currentTarget));const err=validateResult(data);if(err)return feedback(err);let attachments=(x.attachments||[]).slice();try{for(const f of Array.from(q('#hh-result-files').files||[])){if(attachments.length>=MAX_ATTACHMENTS)break;attachments.push(await fileToAttachment(f));}}catch(err){return feedback(err.message);}mutate(resultId?'Result updated.':'Result added.',state=>{const row={...data,entryId,attachments,updatedAt:now()};if(resultId)Object.assign(state.showResults.find(r=>r.id===resultId),row);else state.showResults.push({id:uid('result'),...row,createdAt:now()});});});
  }
  function openAwardForm(entryId,resultId=''){
    const s=normalizeState(readState()),entry=s.showEntries.find(e=>e.id===entryId);if(!entry)return feedback('Show entry not found.');const sh=s.shows.find(x=>x.id===entry.showId);
    setModal('Add award',`<form id="hh-award-form"><div class="form-grid two">${select('Award','awardType',AWARD_TYPES,'Class Winner')}${field('Custom award','customAward','')}${field('Date','date',sh?.startDate||today(),'date')}</div>${textarea('Notes','notes','')}${formActions('Add award')}</form>`,'Shows · Award');
    attachCancel();q('#hh-award-form').addEventListener('submit',e=>{e.preventDefault();const data=Object.fromEntries(new FormData(e.currentTarget));if(data.awardType==='Other'&&!clean(data.customAward))return feedback('Enter the custom award name.');mutate('Award added.',state=>state.showAwards.push({id:uid('award'),...data,resultId:resultId||'',entryId,showId:entry.showId,animalId:entry.animalId,exhibitorId:entry.exhibitorId,createdAt:now()}));});
  }
  function openFinanceForm(kind='Expense',defaults={}){
    const isIncome=kind==='Income';
    setModal(`Add show ${kind.toLowerCase()}`,`<form id="hh-show-finance-form"><div class="form-grid two">${field('Date','date',defaults.date||today(),'date',true)}${select('Type','type',['Expense','Income'],kind)}${field('Category','category',defaults.category||(isIncome?'Prize Money':'Entry Fee'),'text',true)}${field('Amount','amount','0.00','number',true,'min="0.01" step="0.01"')}${field('Vendor or payer','party','')}${field('Description','description',defaults.description||'')}</div>${textarea('Notes','notes','')}${formActions(`Add ${kind.toLowerCase()}`)}</form>`,'Shows · Finance');
    attachCancel();q('#hh-show-finance-form').addEventListener('submit',e=>{e.preventDefault();const data=Object.fromEntries(new FormData(e.currentTarget));const amt=number(data.amount);if(amt<=0)return feedback('Enter an amount greater than zero.');mutate(`${data.type} added to HerdHarbor Finance.`,state=>state.transactions.push({id:uid('transaction'),date:data.date,type:data.type,classification:data.type==='Income'?'':'Operating',category:data.category,scope:defaults.animalId?'Animal':'Operation',species:defaults.animalId?(state.animals.find(a=>a.id===defaults.animalId)?.species||''):'',animalId:defaults.animalId||'',amount:amt.toFixed(2),party:data.party,description:data.description,notes:data.notes,showId:defaults.showId||'',showEntryId:defaults.showEntryId||'',exhibitorId:defaults.exhibitorId||'',projectId:defaults.projectId||'',sourceType:'show',createdAt:now()}));});
  }
  function openHealthForm(animalId,projectId=''){
    const s=normalizeState(readState()),a=s.animals.find(x=>x.id===animalId);if(!a)return feedback('Choose an animal first.');
    setModal('Add health record',`<form id="hh-show-health-form"><div class="form-grid two"><label>Animal<input value="${esc(a.name||a.id)}" disabled></label>${field('Date','date',today(),'date',true)}${select('Record type','type',HEALTH_TYPES,'Observation')}${field('Weight','weight','','number',false,'min="0" step="0.01"')}${select('Weight unit','weightUnit',['lb','oz','kg','g'],'lb')}${field('Follow-up date','followUpDate','','date')}</div>${textarea('Details','details','')}${formActions('Add record')}</form>`,'Health record');attachCancel();q('#hh-show-health-form').addEventListener('submit',e=>{e.preventDefault();const data=Object.fromEntries(new FormData(e.currentTarget));mutate('Health record added to HerdHarbor Health.',state=>state.health.push({id:uid('health'),animalId,...data,projectId,sourceType:'show',createdAt:now()}));});
  }
  function openProjectForm(id=''){
    const s=normalizeState(readState());if(!s.exhibitors.filter(activeRecord).length)return feedback('Add an exhibitor first.');if(!s.animals.length)return feedback('Add an animal first.');const x=s.showProjects.find(p=>p.id===id)||{year:ui.year,status:'Active',projectType:'Rabbit'};
    setModal(id?'Edit project':'Add project',`<form id="hh-project-form"><div class="form-grid two">${field('Project name','projectName',x.projectName,'text',true)}${field('Year','year',x.year||ui.year,'number',true,'min="1900" max="2200" step="1"')}<label>Exhibitor<select name="exhibitorId" required><option value="">Select…</option>${s.exhibitors.filter(activeRecord).map(e=>`<option value="${e.id}" ${e.id===x.exhibitorId?'selected':''}>${esc(exhibitorName(s,e.id))}</option>`).join('')}</select></label><label>Animal<select name="animalId" required><option value="">Select…</option>${animalOptions(s,x.animalId)}</select></label>${select('Project type','projectType',PROJECT_TYPES,x.projectType)}${field('Custom project type','customProjectType',x.customProjectType)}${field('Start date','startDate',x.startDate||today(),'date')}${field('End date','endDate',x.endDate,'date')}${select('Status','status',PROJECT_STATUSES,x.status||'Active')}</div>${textarea('Goals / summary','goalsSummary',x.goalsSummary)}${textarea('Notes','notes',x.notes)}${formActions(id?'Save changes':'Add project')}</form>`,'Shows · Project');
    attachCancel();q('#hh-project-form').addEventListener('submit',e=>{e.preventDefault();const data=Object.fromEntries(new FormData(e.currentTarget));const err=validateProject(data);if(err)return feedback(err);mutate(id?'Project updated.':'Project added.',state=>{if(id)Object.assign(state.showProjects.find(p=>p.id===id),data,{updatedAt:now()});else state.showProjects.push({id:uid('project'),...data,createdAt:now()});});});
  }
  function openGoalForm(projectId){setModal('Add project goal',`<form id="hh-goal-form"><div class="form-grid two">${field('Goal','goal','','text',true)}${field('Target date','targetDate','','date')}${select('Status','status',GOAL_STATUSES,'Not Started')}</div>${textarea('Notes','notes','')}${formActions('Add goal')}</form>`,'Shows · Project');attachCancel();q('#hh-goal-form').addEventListener('submit',e=>{e.preventDefault();const d=Object.fromEntries(new FormData(e.currentTarget));mutate('Project goal added.',s=>s.projectGoals.push({id:uid('goal'),projectId,...d,completedDate:d.status==='Completed'?today():'',createdAt:now()}));});}
  function openProjectNoteForm(projectId){setModal('Add project note',`<form id="hh-project-note-form"><div class="form-grid two">${field('Date','date',today(),'date',true)}${field('Title','title','')}</div>${textarea('Note','note','')}${formActions('Add note')}</form>`,'Shows · Project');attachCancel();q('#hh-project-note-form').addEventListener('submit',e=>{e.preventDefault();const d=Object.fromEntries(new FormData(e.currentTarget));mutate('Project note added.',s=>s.projectNotes.push({id:uid('project_note'),projectId,...d,animalId:s.showProjects.find(p=>p.id===projectId)?.animalId||'',createdAt:now()}));});}
  function openProjectPhotoForm(projectId){setModal('Add project photo',`<form id="hh-project-photo-form"><div class="form-grid two">${field('Date','date',today(),'date',true)}${select('Category','category',PHOTO_CATEGORIES,'Progress')}${field('Caption','caption','')}</div><label>Photo<input id="hh-project-photo-file" type="file" accept="image/*" required></label>${formActions('Add photo')}</form>`,'Shows · Project');attachCancel();q('#hh-project-photo-form').addEventListener('submit',async e=>{e.preventDefault();const file=q('#hh-project-photo-file').files?.[0];if(!file)return feedback('Choose a photo.');let attachment;try{attachment=await fileToAttachment(file);}catch(err){return feedback(err.message);}const d=Object.fromEntries(new FormData(e.currentTarget));mutate('Project photo added.',s=>s.projectPhotos.push({id:uid('project_photo'),projectId,...d,attachment,createdAt:now()}));});}

  function pageHeader(title,description,actions=''){return`<div class="page-header"><div><p class="eyebrow">HerdHarbor Alpha v1.5.1</p><h2>${esc(title)}</h2><p>${esc(description)}</p></div><div class="header-actions">${actions}</div></div>`;}
  function stat(label,value,note=''){return`<article class="stat-card"><span class="label">${esc(label)}</span><strong class="value">${esc(value)}</strong><span class="note">${esc(note)}</span></article>`;}
  function empty(title,text,button=''){return`<div class="hh-shows-empty"><h3>${esc(title)}</h3><p class="muted">${esc(text)}</p>${button}</div>`;}
  function tabs(){const items=[['overview','Overview'],['shows','Shows & Results'],['exhibitors','Exhibitors'],['projects','Projects'],['reports','Reports']];return`<div class="hh-shows-tabs" role="tablist">${items.map(([k,l])=>`<button type="button" class="button ${ui.tab===k?'button-primary':'button-ghost'}" data-shows-tab="${k}">${l}</button>`).join('')}</div>`;}
  function yearOptions(s){const years=new Set([String(new Date().getFullYear()),...s.shows.map(showYear).filter(Boolean),...s.showProjects.map(p=>String(p.year||'')).filter(Boolean)]);return[...years].sort((a,b)=>b.localeCompare(a));}

  function renderOverview(s){
    const yearShows=selectedYearRows(s),showIds=new Set(yearShows.map(x=>x.id)),entries=s.showEntries.filter(e=>showIds.has(e.showId)),entryIds=new Set(entries.map(e=>e.id)),results=s.showResults.filter(r=>entryIds.has(r.entryId)),resultIds=new Set(results.map(r=>r.id)),awards=s.showAwards.filter(a=>showIds.has(a.showId)||resultIds.has(a.resultId)),upcoming=yearShows.filter(x=>x.startDate>=today()&&activeRecord(x)).sort((a,b)=>a.startDate.localeCompare(b.startDate));
    const recentResults=results.slice().sort((a,b)=>String(b.updatedAt||b.createdAt||'').localeCompare(String(a.updatedAt||a.createdAt||''))).slice(0,8);
    const recentAwards=awards.slice().sort((a,b)=>String(b.date||b.createdAt||'').localeCompare(String(a.date||a.createdAt||''))).slice(0,8);
    return`${pageHeader('Shows','Track shows, exhibitors, animals, placements, awards, and competition history.',`<button class="button button-primary" data-add-show>+ Add Show</button><button class="button button-ghost" data-add-result>+ Add Result</button>`)}${tabs()}<div class="hh-shows-toolbar"><label>Year<select data-shows-year>${optionList(yearOptions(s),ui.year)}</select></label></div><div class="stats-grid">${stat('Upcoming Shows',upcoming.length,`${ui.year} scheduled`)}${stat('Shows Entered',new Set(entries.map(e=>e.showId)).size,`${entries.length} classes/entries`)}${stat('Awards Earned',awards.length,`${results.filter(isFirst).length} first-place finishes`)}${stat('Animals Shown',new Set(entries.map(e=>e.animalId)).size,'Unique animals')}</div><div class="dashboard-grid"><section class="panel"><div class="panel-header"><div><h3>Upcoming Shows</h3><small>Scheduled competitions</small></div></div>${upcoming.length?`<div class="list">${upcoming.slice(0,10).map(sh=>{const es=showEntriesFor(s,sh.id);return`<div class="list-item"><div class="list-item-main"><strong>${esc(sh.name)}</strong><span>${fmtDate(sh.startDate)} · ${esc([sh.location,sh.city,sh.state].filter(Boolean).join(', ')||'Location not set')} · ${esc(sh.organization||'Organization not set')}</span><span>${es.length} entries · ${new Set(es.map(e=>e.exhibitorId)).size} exhibitors</span></div><div class="list-item-actions"><button class="button button-ghost button-small" data-view-show="${sh.id}">Open</button></div></div>`;}).join('')}</div>`:empty('No Upcoming Shows','Add a show to begin tracking entries, placements, and awards.','<button class="button button-primary" data-add-show>+ Add Show</button>')}</section><section class="panel"><div class="panel-header"><div><h3>Recent Results</h3><small>Latest placements</small></div></div>${recentResults.length?`<div class="list">${recentResults.map(r=>{const e=s.showEntries.find(x=>x.id===r.entryId),sh=s.shows.find(x=>x.id===e?.showId);return`<div class="list-item"><div class="list-item-main"><strong>${esc(animalName(s,e?.animalId))} · ${esc(resultPlacement(r))}</strong><span>${esc(exhibitorName(s,e?.exhibitorId))} · ${esc(sh?.name||'Show')} · ${esc(e?.className||e?.division||'Class not set')}</span></div></div>`;}).join('')}</div>`:empty('No Results Recorded','Placements and competition results will appear here.')}</section></div><section class="panel hh-shows-section"><div class="panel-header"><div><h3>Recent Awards</h3><small>Latest accomplishments</small></div></div>${recentAwards.length?`<div class="data-table-wrap"><table class="data-table"><thead><tr><th>Award</th><th>Animal</th><th>Exhibitor</th><th>Event</th><th>Date</th></tr></thead><tbody>${recentAwards.map(a=>`<tr><td><strong>${esc(awardLabel(a))}</strong></td><td>${esc(animalName(s,a.animalId))}</td><td>${esc(exhibitorName(s,a.exhibitorId))}</td><td>${esc(showName(s,a.showId))}</td><td>${fmtDate(a.date)}</td></tr>`).join('')}</tbody></table></div>`:empty('No Awards Yet','Awards earned during competitions will appear here.')}</section>`;
  }

  function filteredShows(s){let rows=s.shows.filter(sh=>!ui.year||showYear(sh)===ui.year);if(ui.search){const n=ui.search.toLowerCase();rows=rows.filter(sh=>[sh.name,sh.organization,sh.location,sh.city,sh.state,showTypeLabel(sh)].some(v=>clean(v).toLowerCase().includes(n)));}if(ui.showType)rows=rows.filter(sh=>showTypeLabel(sh)===ui.showType||sh.showType===ui.showType);return rows.sort((a,b)=>String(b.startDate||'').localeCompare(String(a.startDate||'')));}
  function renderShowsTab(s){const rows=filteredShows(s);return`${pageHeader('Shows & Results','Manage competitions, entries, placements, awards, judge notes, and show-specific condition.',`<button class="button button-primary" data-add-show>+ Add Show</button><button class="button button-ghost" data-add-entry>+ Add Entry</button>`)}${tabs()}<section class="panel"><div class="hh-shows-filter-grid"><label>Year<select data-shows-year>${optionList(yearOptions(s),ui.year)}</select></label><label>Search<input data-shows-search value="${esc(ui.search)}" placeholder="Show, organization, location"></label><label>Show type<select data-shows-type><option value="">All types</option>${optionList(SHOW_TYPES,ui.showType)}</select></label></div></section>${rows.length?`<div class="cards-grid hh-shows-card-grid">${rows.map(sh=>{const entries=showEntriesFor(s,sh.id),f=showFinancials(s,sh.id),aw=s.showAwards.filter(a=>a.showId===sh.id);return`<article class="animal-card ${sh.status==='Archived'?'hh-shows-archived':''}"><div class="animal-card-header"><div><span class="badge">${esc(showTypeLabel(sh))}</span><h3>${esc(sh.name)}</h3><p class="meta">${fmtDate(sh.startDate)}${sh.endDate&&sh.endDate!==sh.startDate?` – ${fmtDate(sh.endDate)}`:''}</p></div></div><p>${esc([sh.location,sh.city,sh.state].filter(Boolean).join(', ')||'Location not set')}</p><p class="muted">${esc(sh.organization||'Organization not set')} · ${entries.length} entries · ${aw.length} awards</p><p class="muted">Finance: ${money(f.income)} income · ${money(f.expenses)} expenses · ${money(f.net)} net</p><div class="animal-card-footer"><button class="button button-ghost button-small" data-view-show="${sh.id}">Open</button><button class="button button-ghost button-small" data-edit-show="${sh.id}">Edit</button><button class="button button-ghost button-small" data-add-entry-for="${sh.id}">Add entry</button></div></article>`;}).join('')}</div>`:empty('No Shows Yet','Add your first show to begin tracking entries, placements, and awards.','<button class="button button-primary" data-add-show>+ Add Show</button>')}`;}

  function renderShowDetail(s,showId){const sh=s.shows.find(x=>x.id===showId);if(!sh)return renderShowsTab(s);const entries=showEntriesFor(s,showId),f=showFinancials(s,showId),transactions=s.transactions.filter(t=>t.showId===showId);return`${pageHeader(sh.name,`${fmtDate(sh.startDate)} · ${showTypeLabel(sh)} · ${sh.organization||'Organization not set'}`,`<button class="button button-ghost" data-back-shows>Back</button><button class="button button-primary" data-add-entry-for="${sh.id}">+ Add Entry</button>`)}<div class="stats-grid">${stat('Entries',entries.length,'Classes recorded')}${stat('Awards',s.showAwards.filter(a=>a.showId===sh.id).length,'Accomplishments')}${stat('Show Expenses',money(f.expenses),'From HerdHarbor Finance')}${stat('Net Result',money(f.net),'Income minus expenses')}</div><section class="panel"><div class="panel-header"><div><h3>Entries & Results</h3><small>Multiple classes per animal are supported</small></div></div>${entries.length?`<div class="list">${entries.map(e=>{const a=s.animals.find(x=>x.id===e.animalId),results=resultsForEntry(s,e.id),awards=awardsForEntry(s,e.id);return`<div class="list-item hh-show-entry-row"><div class="list-item-main"><strong>${esc(a?.name||'Unknown animal')} · ${esc(e.className||e.division||'Class not set')}</strong><span>${esc(exhibitorName(s,e.exhibitorId))} · ${esc([a?.species,a?.breed,a?.sex].filter(Boolean).join(' · '))}</span><span>${e.showWeight?`Show weight ${esc(e.showWeight)} ${esc(e.showWeightUnit||'')}`:''}${e.judge?` · Judge ${esc(e.judge)}`:''}</span>${results.map(r=>`<span><b>${esc(resultPlacement(r))}</b>${r.score?` · Score ${esc(r.score)}`:''}${r.comments?` · ${esc(r.comments)}`:''}</span>`).join('')}${awards.length?`<span>${awards.map(a=>`<span class="badge green">${esc(awardLabel(a))}</span>`).join(' ')}</span>`:''}</div><div class="list-item-actions"><button class="button button-ghost button-small" data-edit-entry="${e.id}">Edit</button><button class="button button-ghost button-small" data-add-result-for="${e.id}">Add result</button><button class="button button-ghost button-small" data-add-award-for="${e.id}">Add award</button></div></div>`;}).join('')}</div>`:empty('No Entries Yet','Select an existing HerdHarbor animal and enter it into a class.','<button class="button button-primary" data-add-entry-for="'+sh.id+'">+ Add Entry</button>')}</section><div class="dashboard-grid hh-shows-section"><section class="panel"><div class="panel-header"><div><h3>Show Finance</h3><small>Live view of canonical HerdHarbor Finance transactions</small></div><div class="action-row"><button class="button button-ghost button-small" data-show-expense="${sh.id}">+ Expense</button><button class="button button-ghost button-small" data-show-income="${sh.id}">+ Income</button></div></div>${transactions.length?`<div class="list">${transactions.map(t=>`<div class="list-item"><div class="list-item-main"><strong>${esc(t.category||t.type)} · ${money(t.amount)}</strong><span>${fmtDate(t.date)} · ${esc(t.type)} · ${esc(t.description||t.party||'')}</span></div></div>`).join('')}</div>`:'<p class="muted">No show-linked Finance transactions yet.</p>'}</section><section class="panel"><div class="panel-header"><div><h3>Show Information</h3><small>Historical event details</small></div></div><p><strong>Location:</strong> ${esc([sh.location,sh.city,sh.state].filter(Boolean).join(', ')||'—')}</p><p><strong>Organization:</strong> ${esc(sh.organization||'—')}</p><p><strong>Notes:</strong> ${esc(sh.notes||'—')}</p>${renderAttachmentList(sh.attachments||[])}</section></div>`;}

  function renderExhibitors(s){const rows=s.exhibitors.slice().sort((a,b)=>exhibitorName(s,a.id).localeCompare(exhibitorName(s,b.id)));return`${pageHeader('Exhibitors','Private exhibitor and achievement records for adults, youth, 4-H, FFA, and other participants.','<button class="button button-primary" data-add-exhibitor>+ Add Exhibitor</button>')}${tabs()}${rows.length?`<div class="cards-grid">${rows.map(e=>{const h=exhibitorHistory(s,e.id);return`<article class="animal-card"><div class="animal-card-header"><div><span class="badge">${esc(e.status||'Active')}</span><h3>${esc(exhibitorName(s,e.id))}</h3><p class="meta">${esc([e.club,e.organization,e.county,e.state].filter(Boolean).join(' · ')||'No club/organization set')}</p></div></div><div class="hh-shows-mini-stats"><span>${h.totals.shows} shows</span><span>${h.totals.animals} animals</span><span>${h.totals.firstPlaces} firsts</span><span>${h.totals.championships} championships</span></div><div class="animal-card-footer"><button class="button button-ghost button-small" data-view-exhibitor="${e.id}">Achievements</button><button class="button button-ghost button-small" data-edit-exhibitor="${e.id}">Edit</button></div></article>`;}).join('')}</div>`:empty('No Exhibitors Yet','Add an exhibitor to connect people with animals and competition records.','<button class="button button-primary" data-add-exhibitor>+ Add Exhibitor</button>')}`;}
  function renderExhibitorDetail(s,id){const e=s.exhibitors.find(x=>x.id===id);if(!e)return renderExhibitors(s);const h=exhibitorHistory(s,id);return`${pageHeader(exhibitorName(s,id),'Private exhibitor achievement history.','<button class="button button-ghost" data-back-exhibitors>Back</button>')}<div class="stats-grid">${stat('Shows Attended',h.totals.shows)}${stat('Animals Shown',h.totals.animals)}${stat('First-place Finishes',h.totals.firstPlaces)}${stat('Championships',h.totals.championships)}</div><section class="panel"><div class="panel-header"><h3>Achievement History</h3></div>${h.entries.length?`<div class="data-table-wrap"><table class="data-table"><thead><tr><th>Show</th><th>Animal</th><th>Class</th><th>Placement</th><th>Awards</th></tr></thead><tbody>${h.entries.map(en=>{const r=resultsForEntry(s,en.id),aw=awardsForEntry(s,en.id);return`<tr><td>${esc(showName(s,en.showId))}</td><td>${esc(animalName(s,en.animalId))}</td><td>${esc(en.className||en.division||'—')}</td><td>${esc(r.map(resultPlacement).join(', ')||'—')}</td><td>${esc(aw.map(awardLabel).join(', ')||'—')}</td></tr>`;}).join('')}</tbody></table></div>`:'<p class="muted">No competition records yet.</p>'}</section>`;}

  function renderProjects(s){const rows=s.showProjects.filter(p=>String(p.year)===ui.year).sort((a,b)=>String(b.startDate||'').localeCompare(String(a.startDate||'')));return`${pageHeader('Projects','Optional 4-H, FFA, youth livestock, and other project records linked to existing HerdHarbor data.','<button class="button button-primary" data-add-project>+ Add Project</button>')}${tabs()}<div class="hh-shows-toolbar"><label>Year<select data-shows-year>${optionList(yearOptions(s),ui.year)}</select></label></div>${rows.length?`<div class="cards-grid">${rows.map(p=>{const f=projectFinancials(s,p.id),g=growthSummary(s,p),goals=s.projectGoals.filter(x=>x.projectId===p.id);return`<article class="animal-card"><div class="animal-card-header"><div><span class="badge">${esc(p.status)}</span><h3>${esc(p.projectName)}</h3><p class="meta">${esc(projectTypeLabel(p))} · ${esc(exhibitorName(s,p.exhibitorId))}</p></div></div><p><strong>${esc(animalName(s,p.animalId))}</strong></p><p class="muted">${goals.filter(x=>x.status==='Completed').length}/${goals.length} goals completed · ${g.gain==null?'No growth data':`${g.gain.toFixed(2)} ${esc(g.current?.weightUnit||'')} gain`} · ${money(f.net)} net</p><div class="animal-card-footer"><button class="button button-ghost button-small" data-view-project="${p.id}">Open</button><button class="button button-ghost button-small" data-edit-project="${p.id}">Edit</button></div></article>`;}).join('')}</div>`:empty('No Projects Yet','Create an optional 4-H, FFA, youth livestock, or other project.','<button class="button button-primary" data-add-project>+ Add Project</button>')}`;}
  function renderProjectDetail(s,id){const p=s.showProjects.find(x=>x.id===id);if(!p)return renderProjects(s);const g=growthSummary(s,p),f=projectFinancials(s,id),goals=s.projectGoals.filter(x=>x.projectId===id),notes=s.projectNotes.filter(x=>x.projectId===id).sort((a,b)=>String(b.date).localeCompare(String(a.date))),photos=s.projectPhotos.filter(x=>x.projectId===id),health=s.health.filter(h=>h.animalId===p.animalId).sort((a,b)=>String(b.date||'').localeCompare(String(a.date||''))),timeline=projectTimeline(s,id);return`${pageHeader(p.projectName,`${p.year} · ${projectTypeLabel(p)} · ${exhibitorName(s,p.exhibitorId)}`,`<button class="button button-ghost" data-back-projects>Back</button><button class="button button-primary" data-project-report="${p.id}">Generate Project Report</button>`)}<div class="stats-grid">${stat('Starting Weight',g.start?`${g.start.weight} ${g.start.weightUnit||''}`:'—')}${stat('Current Weight',g.current?`${g.current.weight} ${g.current.weightUnit||''}`:'—')}${stat('Total Gain',g.gain==null?'—':g.gain.toFixed(2))}${stat('Average Daily Gain',g.adg==null?'—':g.adg.toFixed(3))}</div><div class="dashboard-grid"><section class="panel"><div class="panel-header"><div><h3>Goals</h3><small>${goals.filter(x=>x.status==='Completed').length} completed</small></div><button class="button button-ghost button-small" data-add-goal="${p.id}">+ Goal</button></div>${goals.length?`<div class="list">${goals.map(x=>`<div class="list-item"><div class="list-item-main"><strong>${esc(x.goal)}</strong><span>${esc(x.status)}${x.targetDate?` · Target ${fmtDate(x.targetDate)}`:''}</span><span>${esc(x.notes||'')}</span></div></div>`).join('')}</div>`:'<p class="muted">No goals yet.</p>'}</section><section class="panel"><div class="panel-header"><div><h3>Project Finance</h3><small>From canonical HerdHarbor Finance</small></div><div class="action-row"><button class="button button-ghost button-small" data-project-expense="${p.id}">+ Expense</button><button class="button button-ghost button-small" data-project-income="${p.id}">+ Income</button></div></div><p><strong>Expenses:</strong> ${money(f.expenses)}</p><p><strong>Income:</strong> ${money(f.income)}</p><p><strong>Net project result:</strong> ${money(f.net)}</p></section></div><div class="dashboard-grid hh-shows-section"><section class="panel"><div class="panel-header"><div><h3>Health History</h3><small>Existing HerdHarbor Health records</small></div><button class="button button-ghost button-small" data-add-health="${p.animalId}" data-project="${p.id}">+ Health Record</button></div>${health.length?`<div class="list">${health.slice(0,12).map(h=>`<div class="list-item"><div class="list-item-main"><strong>${esc(h.type)}</strong><span>${fmtDate(h.date)}${h.weight?` · ${esc(h.weight)} ${esc(h.weightUnit||'')}`:''}</span><span>${esc(h.details||h.notes||'')}</span></div></div>`).join('')}</div>`:'<p class="muted">No Health records for this animal yet.</p>'}</section><section class="panel"><div class="panel-header"><div><h3>Notes & Photos</h3><small>Project journal</small></div><div class="action-row"><button class="button button-ghost button-small" data-add-project-note="${p.id}">+ Note</button><button class="button button-ghost button-small" data-add-project-photo="${p.id}">+ Photo</button></div></div>${notes.slice(0,8).map(n=>`<p><strong>${fmtDate(n.date)} · ${esc(n.title||'Note')}</strong><br>${esc(n.note||'')}</p>`).join('')||'<p class="muted">No project notes yet.</p>'}${photos.length?`<div class="hh-shows-photo-grid">${photos.slice(0,12).map(ph=>`<figure><img src="${esc(ph.attachment?.dataUrl||'')}" alt="${esc(ph.caption||'Project photo')}"><figcaption>${esc(ph.category)} · ${esc(ph.caption||'')}</figcaption></figure>`).join('')}</div>`:''}</section></div><section class="panel hh-shows-section"><div class="panel-header"><h3>Project Timeline</h3></div>${timeline.length?`<div class="list">${timeline.slice(0,40).map(t=>`<div class="list-item"><div class="list-item-main"><strong>${fmtDate(t.date)} · ${esc(t.title)}</strong><span>${esc(t.type)} · ${esc(t.detail||'')}</span></div></div>`).join('')}</div>`:'<p class="muted">Timeline events will appear from existing project, Health, Finance, Shows, goals, photos, and notes.</p>'}</section>`;}

  function renderReports(s){return`${pageHeader('Shows Reports','Generate breeder and project records from existing HerdHarbor data.')}${tabs()}<div class="dashboard-grid"><section class="panel"><div class="panel-header"><h3>Show & Awards Report</h3></div><div class="form-grid two"><label>Year<select id="hh-report-year">${optionList(yearOptions(s),ui.year)}</select></label><label>Exhibitor<select id="hh-report-exhibitor"><option value="">All exhibitors</option>${s.exhibitors.map(e=>`<option value="${e.id}">${esc(exhibitorName(s,e.id))}</option>`).join('')}</select></label><label>Animal<select id="hh-report-animal"><option value="">All animals</option>${animalOptions(s,'')}</select></label><label>Species<input id="hh-report-species" placeholder="All species"></label><label>Organization<input id="hh-report-organization" placeholder="All organizations"></label></div><div class="action-row"><button class="button button-primary" data-show-awards-report>Generate Show & Awards Report</button></div></section><section class="panel"><div class="panel-header"><h3>Project Record</h3></div><p class="muted">HerdHarbor Project Record summarizes project information, goals, growth, Health, Finance, shows, awards, photos, and notes. It is not automatically an official state or county 4-H record book.</p><label>Project<select id="hh-project-report-select"><option value="">Select project…</option>${s.showProjects.map(p=>`<option value="${p.id}">${esc(p.projectName)} · ${esc(p.year)}</option>`).join('')}</select></label><div class="action-row"><button class="button button-primary" data-project-report-selected>Generate Project Record</button></div></section></div>`;}

  function printWindow(title,body){const w=window.open('','_blank','noopener,noreferrer');if(!w)return feedback('Allow pop-ups to generate this report.');w.document.write(`<!doctype html><html><head><meta charset="utf-8"><title>${esc(title)}</title><style>body{font-family:Arial,sans-serif;color:#18212A;margin:28px}h1,h2,h3{color:#0D2540}table{width:100%;border-collapse:collapse;margin:12px 0 22px}th,td{padding:7px;border-bottom:1px solid #ccd4da;text-align:left;vertical-align:top}.meta{color:#65727E}.grid{display:grid;grid-template-columns:repeat(4,1fr);gap:10px}.card{border:1px solid #ccd4da;border-radius:8px;padding:10px}.photos{display:grid;grid-template-columns:repeat(3,1fr);gap:8px}.photos img{max-width:100%;max-height:180px;object-fit:contain}@media print{body{margin:.35in}.no-print{display:none}.grid{grid-template-columns:repeat(4,1fr)}tr{break-inside:avoid}}</style></head><body><div class="no-print"><button onclick="window.print()">Print / Save PDF</button></div>${body}</body></html>`);w.document.close();}
  function generateShowAwardsReport(filters={}){const s=normalizeState(readState()),year=safeYear(filters.year||ui.year);let shows=s.shows.filter(sh=>showYear(sh)===year);if(filters.organization)shows=shows.filter(sh=>clean(sh.organization).toLowerCase().includes(clean(filters.organization).toLowerCase()));const showIds=new Set(shows.map(x=>x.id));let entries=s.showEntries.filter(e=>showIds.has(e.showId));if(filters.exhibitorId)entries=entries.filter(e=>e.exhibitorId===filters.exhibitorId);if(filters.animalId)entries=entries.filter(e=>e.animalId===filters.animalId);if(filters.species)entries=entries.filter(e=>(s.animals.find(a=>a.id===e.animalId)?.species||'').toLowerCase().includes(clean(filters.species).toLowerCase()));const rows=entries.map(e=>({entry:e,show:s.shows.find(sh=>sh.id===e.showId),animal:s.animals.find(a=>a.id===e.animalId),results:resultsForEntry(s,e.id),awards:awardsForEntry(s,e.id)}));const totals={shows:new Set(rows.map(r=>r.entry.showId)).size,classes:rows.length,firsts:rows.flatMap(r=>r.results).filter(isFirst).length,awards:rows.flatMap(r=>r.awards).length,championships:rows.flatMap(r=>r.awards).filter(isChampionship).length};printWindow(`HerdHarbor Show & Awards Report ${year}`,`<h1>HerdHarbor Show & Awards Report</h1><p class="meta">${esc(year)} · Generated ${fmtDate(today())}</p><div class="grid"><div class="card"><b>${totals.shows}</b><br>Shows</div><div class="card"><b>${totals.classes}</b><br>Classes</div><div class="card"><b>${totals.firsts}</b><br>First places</div><div class="card"><b>${totals.awards}</b><br>Awards</div></div><table><thead><tr><th>Show</th><th>Animal</th><th>Exhibitor</th><th>Class</th><th>Placement</th><th>Awards</th><th>Judge comments</th></tr></thead><tbody>${rows.map(r=>`<tr><td>${esc(r.show?.name||'')}</td><td>${esc(r.animal?.name||'')}</td><td>${esc(exhibitorName(s,r.entry.exhibitorId))}</td><td>${esc(r.entry.className||r.entry.division||'')}</td><td>${esc(r.results.map(resultPlacement).join(', '))}</td><td>${esc(r.awards.map(awardLabel).join(', '))}</td><td>${esc(r.results.map(x=>x.comments).filter(Boolean).join(' · '))}</td></tr>`).join('')}</tbody></table>`);return{rows,totals};}
  function generateProjectReport(projectId){const s=normalizeState(readState()),p=s.showProjects.find(x=>x.id===projectId);if(!p)return null;const a=s.animals.find(x=>x.id===p.animalId),g=growthSummary(s,p),f=projectFinancials(s,p.id),goals=s.projectGoals.filter(x=>x.projectId===p.id),notes=s.projectNotes.filter(x=>x.projectId===p.id),photos=s.projectPhotos.filter(x=>x.projectId===p.id),health=s.health.filter(h=>h.animalId===p.animalId),entries=s.showEntries.filter(e=>e.projectId===p.id),transactions=s.transactions.filter(t=>t.projectId===p.id);printWindow(`${p.projectName} · HerdHarbor Project Record`,`<h1>HerdHarbor Project Record</h1><p class="meta">This report summarizes information recorded in HerdHarbor. It is not automatically an official state or county 4-H record book.</p><h2>${esc(p.projectName)}</h2><p>${esc(p.year)} · ${esc(projectTypeLabel(p))} · ${esc(exhibitorName(s,p.exhibitorId))}</p><h3>Animal</h3><p><b>${esc(a?.name||'')}</b> · ${esc([a?.species,a?.breed,a?.sex,a?.color].filter(Boolean).join(' · '))}</p><h3>Goals</h3><table><tbody>${goals.map(x=>`<tr><td>${esc(x.goal)}</td><td>${esc(x.status)}</td><td>${fmtDate(x.targetDate)}</td><td>${esc(x.notes||'')}</td></tr>`).join('')}</tbody></table><h3>Growth</h3><p>Starting: ${g.start?`${esc(g.start.weight)} ${esc(g.start.weightUnit||'')}`:'—'} · Current: ${g.current?`${esc(g.current.weight)} ${esc(g.current.weightUnit||'')}`:'—'} · Total gain: ${g.gain==null?'—':g.gain.toFixed(2)} · Average daily gain: ${g.adg==null?'—':g.adg.toFixed(3)}</p><h3>Health History</h3><table><tbody>${health.map(h=>`<tr><td>${fmtDate(h.date)}</td><td>${esc(h.type)}</td><td>${esc(h.details||h.notes||'')}</td></tr>`).join('')}</tbody></table><h3>Financial Records</h3><p>Expenses ${money(f.expenses)} · Income ${money(f.income)} · Net ${money(f.net)}</p><table><tbody>${transactions.map(t=>`<tr><td>${fmtDate(t.date)}</td><td>${esc(t.type)}</td><td>${esc(t.category||'')}</td><td>${money(t.amount)}</td><td>${esc(t.description||'')}</td></tr>`).join('')}</tbody></table><h3>Shows, Placements & Awards</h3><table><tbody>${entries.map(e=>`<tr><td>${esc(showName(s,e.showId))}</td><td>${esc(e.className||e.division||'')}</td><td>${esc(resultsForEntry(s,e.id).map(resultPlacement).join(', '))}</td><td>${esc(awardsForEntry(s,e.id).map(awardLabel).join(', '))}</td></tr>`).join('')}</tbody></table><h3>Project Notes</h3>${notes.map(n=>`<p><b>${fmtDate(n.date)} · ${esc(n.title||'Note')}</b><br>${esc(n.note||'')}</p>`).join('')}<h3>Photos</h3><div class="photos">${photos.map(ph=>`<figure><img src="${esc(ph.attachment?.dataUrl||'')}" alt="${esc(ph.caption||'Project photo')}"><figcaption>${esc(ph.category)} · ${esc(ph.caption||'')}</figcaption></figure>`).join('')}</div>`);return{project:p,growth:g,finance:f};}

  function render(){const host=q('#view-shows');if(!host)return;const s=normalizeState(readState());if(ui.detail?.type==='show')host.innerHTML=renderShowDetail(s,ui.detail.id);else if(ui.detail?.type==='exhibitor')host.innerHTML=renderExhibitorDetail(s,ui.detail.id);else if(ui.detail?.type==='project')host.innerHTML=renderProjectDetail(s,ui.detail.id);else if(ui.tab==='shows')host.innerHTML=renderShowsTab(s);else if(ui.tab==='exhibitors')host.innerHTML=renderExhibitors(s);else if(ui.tab==='projects')host.innerHTML=renderProjects(s);else if(ui.tab==='reports')host.innerHTML=renderReports(s);else host.innerHTML=renderOverview(s);bind(host,s);}
  function activate(){qa('.view').forEach(v=>v.classList.remove('active'));q('#view-shows')?.classList.add('active');qa('.nav-item').forEach(n=>n.classList.toggle('active',n.dataset.route==='shows'));q('#sidebar')?.classList.remove('open');if(location.hash!=='#shows')history.replaceState(null,'','#shows');render();}
  function injectShell(){const litters=q('.nav-item[data-route="litters"]');if(litters&&!q('.nav-item[data-route="shows"]')){const b=document.createElement('button');b.className='nav-item';b.dataset.route='shows';b.title='Shows';b.innerHTML='<span class="nav-icon">★</span><span>Shows</span>';litters.insertAdjacentElement('afterend',b);b.addEventListener('click',e=>{e.preventDefault();ui.detail=null;activate();});}
    const main=q('.main-content');if(main&&!q('#view-shows')){const sec=document.createElement('section');sec.id='view-shows';sec.className='view';const lit=q('#view-litters');lit?lit.insertAdjacentElement('afterend',sec):main.appendChild(sec);} }
  function bind(host,s){qa('[data-shows-tab]',host).forEach(b=>b.addEventListener('click',()=>{ui.tab=b.dataset.showsTab;ui.detail=null;ui.page=1;render();}));qa('[data-shows-year]',host).forEach(sel=>sel.addEventListener('change',()=>{ui.year=safeYear(sel.value);ui.detail=null;render();}));q('[data-shows-search]',host)?.addEventListener('input',e=>{ui.search=e.target.value;render();});q('[data-shows-type]',host)?.addEventListener('change',e=>{ui.showType=e.target.value;render();});
    qa('[data-add-show]',host).forEach(b=>b.addEventListener('click',()=>openShowForm()));qa('[data-edit-show]',host).forEach(b=>b.addEventListener('click',()=>openShowForm(b.dataset.editShow)));qa('[data-view-show]',host).forEach(b=>b.addEventListener('click',()=>{ui.detail={type:'show',id:b.dataset.viewShow};render();}));qa('[data-back-shows]',host).forEach(b=>b.addEventListener('click',()=>{ui.detail=null;ui.tab='shows';render();}));
    qa('[data-add-exhibitor]',host).forEach(b=>b.addEventListener('click',()=>openExhibitorForm()));qa('[data-edit-exhibitor]',host).forEach(b=>b.addEventListener('click',()=>openExhibitorForm(b.dataset.editExhibitor)));qa('[data-view-exhibitor]',host).forEach(b=>b.addEventListener('click',()=>{ui.detail={type:'exhibitor',id:b.dataset.viewExhibitor};render();}));qa('[data-back-exhibitors]',host).forEach(b=>b.addEventListener('click',()=>{ui.detail=null;ui.tab='exhibitors';render();}));
    qa('[data-add-entry]',host).forEach(b=>b.addEventListener('click',()=>openEntryForm()));qa('[data-add-entry-for]',host).forEach(b=>b.addEventListener('click',()=>openEntryForm('',{showId:b.dataset.addEntryFor})));qa('[data-edit-entry]',host).forEach(b=>b.addEventListener('click',()=>openEntryForm(b.dataset.editEntry)));qa('[data-add-result-for]',host).forEach(b=>b.addEventListener('click',()=>openResultForm(b.dataset.addResultFor)));qa('[data-add-award-for]',host).forEach(b=>b.addEventListener('click',()=>openAwardForm(b.dataset.addAwardFor)));
    qa('[data-add-result]',host).forEach(b=>b.addEventListener('click',()=>{const entries=s.showEntries;if(!entries.length)return feedback('Add a show entry first.');setModal('Choose entry',`<div class="list">${entries.slice(-30).reverse().map(e=>`<button type="button" class="list-item hh-shows-entry-choice" data-choose-result-entry="${e.id}"><span class="list-item-main"><strong>${esc(animalName(s,e.animalId))}</strong><span>${esc(showName(s,e.showId))} · ${esc(e.className||e.division||'Class')}</span></span></button>`).join('')}</div><div class="form-actions"><button class="button button-ghost" data-shows-cancel>Cancel</button></div>`);attachCancel();qa('[data-choose-result-entry]').forEach(x=>x.addEventListener('click',()=>openResultForm(x.dataset.chooseResultEntry)));}));
    qa('[data-show-expense]',host).forEach(b=>b.addEventListener('click',()=>openFinanceForm('Expense',{showId:b.dataset.showExpense,category:'Entry Fee',description:`${showName(s,b.dataset.showExpense)} entry/show expense`})));qa('[data-show-income]',host).forEach(b=>b.addEventListener('click',()=>openFinanceForm('Income',{showId:b.dataset.showIncome,category:'Prize Money',description:`${showName(s,b.dataset.showIncome)} prize/premium`})));
    qa('[data-add-project]',host).forEach(b=>b.addEventListener('click',()=>openProjectForm()));qa('[data-edit-project]',host).forEach(b=>b.addEventListener('click',()=>openProjectForm(b.dataset.editProject)));qa('[data-view-project]',host).forEach(b=>b.addEventListener('click',()=>{ui.detail={type:'project',id:b.dataset.viewProject};render();}));qa('[data-back-projects]',host).forEach(b=>b.addEventListener('click',()=>{ui.detail=null;ui.tab='projects';render();}));qa('[data-add-goal]',host).forEach(b=>b.addEventListener('click',()=>openGoalForm(b.dataset.addGoal)));qa('[data-add-project-note]',host).forEach(b=>b.addEventListener('click',()=>openProjectNoteForm(b.dataset.addProjectNote)));qa('[data-add-project-photo]',host).forEach(b=>b.addEventListener('click',()=>openProjectPhotoForm(b.dataset.addProjectPhoto)));qa('[data-add-health]',host).forEach(b=>b.addEventListener('click',()=>openHealthForm(b.dataset.addHealth,b.dataset.project||'')));qa('[data-project-expense]',host).forEach(b=>b.addEventListener('click',()=>{const p=s.showProjects.find(x=>x.id===b.dataset.projectExpense);openFinanceForm('Expense',{projectId:p.id,animalId:p.animalId,exhibitorId:p.exhibitorId,category:'Show/Project Expense',description:p.projectName});}));qa('[data-project-income]',host).forEach(b=>b.addEventListener('click',()=>{const p=s.showProjects.find(x=>x.id===b.dataset.projectIncome);openFinanceForm('Income',{projectId:p.id,animalId:p.animalId,exhibitorId:p.exhibitorId,category:'Prize Money',description:p.projectName});}));
    qa('[data-project-report]',host).forEach(b=>b.addEventListener('click',()=>generateProjectReport(b.dataset.projectReport)));q('[data-project-report-selected]',host)?.addEventListener('click',()=>{const id=q('#hh-project-report-select')?.value;if(!id)return feedback('Choose a project.');generateProjectReport(id);});q('[data-show-awards-report]',host)?.addEventListener('click',()=>generateShowAwardsReport({year:q('#hh-report-year')?.value,exhibitorId:q('#hh-report-exhibitor')?.value,animalId:q('#hh-report-animal')?.value,species:q('#hh-report-species')?.value,organization:q('#hh-report-organization')?.value}));
  }

  function start(){injectShell();window.addEventListener('hashchange',()=>{if(location.hash==='#shows')activate();});document.addEventListener('click',e=>{const a=e.target.closest('.nav-item[data-route="shows"]');if(a){e.preventDefault();activate();}});let ret=null;try{ret=JSON.parse(sessionStorage.getItem(RETURN_KEY)||'null');sessionStorage.removeItem(RETURN_KEY);}catch{}if(ret){ui.tab=ret.tab||ui.tab;ui.year=ret.year||ui.year;setTimeout(()=>{activate();if(ret.message)feedback(ret.message,'success');},0);}else if(location.hash==='#shows')setTimeout(activate,0);}

  return Object.freeze({VERSION,COLLECTIONS,SHOW_TYPES,AWARD_TYPES,PROJECT_TYPES,PLACEMENTS,normalizeState,financialSummary,showFinancials,projectFinancials,animalHistory,exhibitorHistory,growthSummary,projectTimeline,validateShow,validateEntry,validateResult,validateProject,generateShowAwardsReport,generateProjectReport,start});
});